      {"id": "wb-11.1-01", "type": "num", "diff": 1, "skill": "cost-function-value", "source": "wb", "lang": "en", "q": "The cost of hiring a ladder has two parts: a delivery charge of $10 plus $5 for each day. What is the cost of hiring the ladder for 6 days?", "svg": null, "choices": null, "answer": 40, "accept": [], "tol": 0, "unitLabel": "$", "hints": ["Phần nào của chi phí chỉ trả một lần, phần nào trả theo số ngày?", "Phần theo ngày với 6 ngày là bao nhiêu?", "Cộng phí giao hàng vào phần đó."], "explain": "6 ngày: 5 × 6 = 30 đô, cộng phí giao hàng 10 đô: tổng 40 đô.", "why": null},
      {"id": "wb-11.1-02", "howto": "Write a formula for the total cost y using the number of tickets t.", "type": "text", "diff": 2, "skill": "write-function", "source": "wb", "lang": "en", "q": "Cinema tickets cost $8 each and there is a single booking fee of $4. The total cost of booking t tickets is $y. Write a function for y in terms of t.", "svg": null, "choices": null, "answer": "y=8t+4", "accept": ["y=4+8t", "y=8×t+4", "y=8*t+4", "y=t*8+4", "y=4+8×t"], "tol": 0, "unitLabel": "", "hints": ["Phần nào thay đổi theo số vé t, phần nào cố định?", "Phần thay đổi: 8 đô nhân với t. Phần cố định là bao nhiêu?", "Viết y bằng phần thay đổi cộng phần cố định."], "explain": "Giá vé: 8t; phí đặt vé cố định: 4. Vậy y = 8t + 4. Phí đặt vé chỉ cộng một lần, không nhân với t.", "why": null},
      {"id": "wb-11.1-03", "howto": "Write a formula for the number of litres L left in the tank using the number of hours t.", "type": "text", "diff": 2, "skill": "write-formula", "source": "wb", "lang": "en", "q": "A car has 37 litres of petrol at the start of a journey and uses 6 litres every hour. There are L litres in the tank after t hours. Write a formula for L.", "svg": null, "choices": null, "answer": "L=37-6t", "accept": ["l=-6t+37", "l=37-6×t", "l=37-6*t", "l=37-t*6"], "tol": 0, "unitLabel": "", "hints": ["Xăng lúc đầu là bao nhiêu? Sau 1 giờ còn bao nhiêu?", "Sau t giờ, lượng xăng đã dùng là bao nhiêu?", "Lấy lượng xăng ban đầu trừ lượng đã dùng."], "explain": "Xăng đã dùng sau t giờ là 6t, nên L = 37 − 6t. Kiểm tra t = 2: 37 − 12 = 25 lít.", "why": null},
      {"id": "wb-11.1-04", "type": "num", "diff": 1, "skill": "function-substitute", "source": "wb", "lang": "en", "q": "A gardener plants a tree. After t years its height is h metres, where h = 2t + 3. What is the height after 6 years?", "svg": null, "choices": null, "answer": 15, "accept": [], "tol": 0, "unitLabel": "m", "hints": ["Chữ t là gì? Thay t bằng số nào?", "Tính 2 × 6 trước.", "Rồi cộng 3."], "explain": "h = 2 × 6 + 3 = 12 + 3 = 15 mét.", "why": null},
      {"id": "wb-11.1-05", "howto": "Write a formula for the man's age m using the woman's age w.", "type": "text", "diff": 2, "skill": "age-function", "source": "wb", "lang": "en", "q": "A man is 5 years more than twice a woman's age. The woman is w years old and the man is m years old. Write a function for m in terms of w.", "svg": null, "choices": null, "answer": "m=2w+5", "accept": ["m=5+2w", "m=2×w+5", "m=2*w+5", "m=w*2+5"], "tol": 0, "unitLabel": "", "hints": ["'Hai lần tuổi người phụ nữ' viết thế nào theo w?", "'Hơn 5 tuổi' nghĩa là cộng hay trừ 5?", "Ghép hai phần lại thành m = …"], "explain": "Hai lần tuổi người phụ nữ là 2w, rồi cộng 5: m = 2w + 5. Kiểm tra w = 20: m = 45.", "why": null},
      {"id": "wb-11.1-06", "type": "mc", "diff": 2, "skill": "describe-function", "source": "wb", "lang": "en", "q": "A boy is b years old and a girl is g years old, where g = 3b − 6. Which statement describes the relationship?", "svg": null, "choices": ["The girl is 6 years younger than 3 times the boy's age", "The girl is 6 years older than 3 times the boy's age", "The girl is 3 years older than 6 times the boy's age", "The girl is 6 years younger than the boy"], "answer": 0, "accept": [], "tol": 0, "unitLabel": "", "hints": ["Hãy thử với b = 5: g bằng bao nhiêu?", "3b là gì so với tuổi của bạn trai? Rồi trừ 6 nghĩa là gì?", "So sánh với các câu mô tả: dấu − 6 có đổi thành + 6 được không?"], "explain": "3b là ba lần tuổi bạn trai, trừ 6: bạn gái ít hơn ba lần tuổi bạn trai 6 tuổi. Với b = 5 thì g = 9. Lỗi hay gặp: đọc dấu − thành 'hơn'.", "why": null},
      {"id": "wb-11.1-07", "type": "mc", "diff": 2, "skill": "interpret-function", "source": "wb", "lang": "en", "q": "Here is a function: y = 30x + 15, where x is the number of hours. Which situation could it describe?", "svg": null, "choices": ["A fixed charge of $30 plus $15 per hour", "A fixed charge of $15 plus $30 per hour", "$45 for every hour", "$15 for the first hour only"], "answer": 1, "accept": [], "tol": 0, "unitLabel": "", "hints": ["Số nào đứng cùng x: nó thay đổi theo số giờ hay không?", "Khi x = 0 (chưa dùng giờ nào), y bằng bao nhiêu? Đó là khoản nào?", "Số đi với x là mức tính cho mỗi giờ."], "explain": "Khi x = 0 thì y = 15: đó là phí cố định $15. Số 30 nhân với x là $30 mỗi giờ. Lỗi: đổi chỗ phí cố định và phí mỗi giờ.", "why": null},
      {"id": "wb-11.1-08", "howto": "Compare two costs: hiring for 14 days, and double the cost of hiring for 7 days. Enter how many dollars cheaper the 14-day hire is.", "type": "num", "diff": 3, "skill": "fixed-cost-once", "source": "wb", "lang": "en", "q": "The cost, in dollars, of hiring a bike for n days is 5n + 10. How many dollars less is the cost of hiring for 14 days than twice the cost of hiring for 7 days?", "svg": null, "choices": null, "answer": 10, "accept": [], "tol": 0, "unitLabel": "$", "hints": ["Tính chi phí thuê 7 ngày, rồi nhân đôi.", "Tính chi phí thuê 14 ngày.", "Lấy hai kết quả trừ cho nhau. Phí 10 đô được trả mấy lần mỗi cách?"], "explain": "7 ngày: 5 × 7 + 10 = 45; gấp đôi = 90. 14 ngày: 5 × 14 + 10 = 80. Chênh 10 đô, vì phí cố định 10 đô chỉ tính một lần với 14 ngày nhưng hai lần khi thuê hai đợt 7 ngày.", "why": null},
      {"id": "wb-11.1-09", "type": "num", "diff": 2, "skill": "daily-rate", "source": "wb", "lang": "en", "q": "The cost, in dollars, of hiring a bike for n days is 5n + 10. Zara hires the bike for a number of days but returns it one day early. She is refunded for the unused day only. How many dollars is the refund?", "svg": null, "choices": null, "answer": 5, "accept": [], "tol": 0, "unitLabel": "$", "hints": ["Khi thêm một ngày thuê (n tăng 1), chi phí tăng bao nhiêu?", "Phí cố định 10 đô có được hoàn lại không?", "Khoản hoàn bằng đúng mức chi phí của một ngày."], "explain": "Mỗi ngày tính thêm 5 đô, còn 10 đô là phí cố định không hoàn lại. Hoàn 5 đô.", "why": null},
      {"id": "wb-11.1-10", "howto": "Enter the woman's age at the moment when the man is exactly three times as old as her.", "type": "num", "diff": 3, "skill": "solve-from-function", "source": "wb", "lang": "en", "q": "A man is 5 years more than twice a woman's age (m = 2w + 5). How old is the woman when the man is exactly three times as old as she is?", "svg": null, "choices": null, "answer": 5, "accept": [], "tol": 0, "unitLabel": "", "hints": ["'Gấp ba lần tuổi cô ấy' viết thế nào theo w?", "Đặt 2w + 5 bằng 3w.", "Giải phương trình này tìm w."], "explain": "2w + 5 = 3w nên w = 5. Khi đó người đàn ông 2 × 5 + 5 = 15 tuổi, đúng bằng 3 × 5.", "why": null}
