      {"id": "wb-11.2-06", "howto": "Write a formula for the perimeter p using only the width x.", "type": "text", "diff": 3, "skill": "perimeter-function", "source": "wb", "lang": "en", "q": "A rectangle has width x cm and length 3 cm more than its width. Its perimeter is p cm. Write a function for p in terms of x.", "svg": null, "choices": null, "answer": "p=4x+6", "accept": ["p=6+4x", "p=2(2x+3)", "p=2(x+x+3)", "p=x+x+x+3+x+x+3", "p=2x+2(x+3)", "p=2x+2x+6", "p=4×x+6"], "tol": 0, "unitLabel": "", "hints": ["Chiều dài viết thế nào theo x?", "Chu vi = 2 × (dài + rộng). Viết tổng dài và rộng theo x.", "Nhân 2 vào cả biểu thức rồi rút gọn."], "explain": "Chiều dài là x + 3. Chu vi p = 2(x + x + 3) = 2(2x + 3) = 4x + 6.", "why": null},
      {"id": "wb-11.2-07", "type": "num", "diff": 3, "skill": "solve-perimeter", "source": "wb", "lang": "en", "q": "A rectangle has width x cm and length (x + 3) cm, so its perimeter is p = 4x + 6. The perimeter is 20 cm. What is the width, in cm?", "svg": null, "choices": null, "answer": 3.5, "accept": [], "tol": 0.001, "unitLabel": "cm", "hints": ["Đặt p = 20 vào công thức: 4x + 6 = 20.", "Hoàn tác + 6: 4x bằng bao nhiêu?", "Chia cho 4."], "explain": "4x + 6 = 20 ⇒ 4x = 14 ⇒ x = 3,5 cm. Kiểm tra: dài 6,5; chu vi 2 × (3,5 + 6,5) = 20.", "why": null},
      {"id": "wb-11.2-08", "type": "num", "diff": 3, "skill": "intersection-lines", "source": "wb", "lang": "en", "q": "The lines y = 5x + 20 and y = 30 − 5x are drawn on the same axes. What is the x-coordinate of the point where they cross?", "svg": null, "choices": null, "answer": 1, "accept": [], "tol": 0, "unitLabel": "", "hints": ["Tại giao điểm, hai giá trị y như thế nào?", "Đặt 5x + 20 = 30 − 5x.", "Gom các số hạng x về một vế rồi giải."], "explain": "5x + 20 = 30 − 5x ⇒ 10x = 10 ⇒ x = 1. Khi đó y = 25 cho cả hai đường: hai đường cắt nhau tại (1, 25).", "why": null},
      {"id": "wb-11.2-09", "type": "num", "diff": 2, "skill": "read-time", "source": "wb", "lang": "en", "q": "The temperature (T °C) after m minutes is given by T = 70 − 6m. After how many minutes is the temperature 55 °C?", "svg": null, "choices": null, "answer": 2.5, "accept": [], "tol": 0.001, "unitLabel": "min", "hints": ["Đặt T = 55 trong công thức: 70 − 6m = 55.", "Chuyển 6m sang một vế: 6m bằng bao nhiêu?", "Chia cho 6."], "explain": "70 − 6m = 55 ⇒ 6m = 15 ⇒ m = 2,5 phút.", "why": null}
